 static Style GridHeaderStyle(bool dark,Brush bg,Brush fg,Brush border){var s=new Style(typeof(DataGridColumnHeader));s.Setters.Add(new Setter(Control.BackgroundProperty,bg));s.Setters.Add(new Setter(Control.ForegroundProperty,fg));s.Setters.Add(new Setter(Control.BorderBrushProperty,border));s.Setters.Add(new Setter(Control.BorderThicknessProperty,new Thickness(0,0,0,1)));s.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(10,7,10,7)));s.Setters.Add(new Setter(Control.FontWeightProperty,FontWeights.SemiBold));return s;}
