 void Panel_Click(object s,RoutedEventArgs e){_panelVisible=!_panelVisible;OutputCard.Visibility=_panelVisible?Visibility.Visible:Visibility.Collapsed;MainSplitter.Visibility=_panelVisible?Visibility.Visible:Visibility.Collapsed;var cols=((Grid)EditorCard.Parent).ColumnDefinitions;cols[2].Width=_panelVisible?new GridLength(1,GridUnitType.Star):new GridLength(0);cols[2].MinWidth=_panelVisible?300:0;PanelButton.Content=_panelVisible?"◧  Panel":"◨  Panel";StatusText.Text=_panelVisible?"Το δεξί panel εμφανίστηκε":"Το δεξί panel αποκρύφθηκε";}
 void Focus_Click(object s,RoutedEventArgs e){_focusMode=!_focusMode;TopBar.Visibility=_focusMode?Visibility.Collapsed:Visibility.Visible;Toolbar.Visibility=_focusMode?Visibility.Collapsed:Visibility.Visible;StatusBar.Visibility=_focusMode?Visibility.Collapsed:Visibility.Visible;Root.RowDefinitions[0].Height=_focusMode?new GridLength(0):new GridLength(64);Root.RowDefinitions[1].Height=_focusMode?new GridLength(0):new GridLength(48);Root.RowDefinitions[3].Height=_focusMode?new GridLength(0):new GridLength(30);if(_focusMode&&_panelVisible)Panel_Click(s,e);else if(!_focusMode&&!_panelVisible)Panel_Click(s,e);FocusButton.Content=_focusMode?"▣  Exit Focus":"▣  Focus";Editor.Focus();}
 void Theme_Click(object s,RoutedEventArgs e){_dark=!_dark;ApplyTheme();if(WorkTabs.SelectedIndex==1)BuildFlowchart();}
