 void WorkTabs_SelectionChanged(object s,SelectionChangedEventArgs e){if(IsLoaded&&WorkTabs.SelectedIndex==1)BuildFlowchart();}
 void BuildFlowchart(){
  FlowCanvas.Children.Clear();_flowShapes.Clear();FlowCanvas.Background=B(_dark?"#0F192B":"#F8FAFC");var lines=CodeText().Replace("\r","").Split('\n');const double cx=380,w=190,h=44;double y=28;AddFlowNode(0,"ΑΡΧΗ",cx,y,w,h,"start");y+=82;
  for(int i=0;i<lines.Length;i++){var t=lines[i].Trim();if(SkipFlow(t))continue;if(t.StartsWith("ΟΣΟ ",StringComparison.OrdinalIgnoreCase)&&t.EndsWith(" ΕΠΑΝΑΛΑΒΕ",StringComparison.OrdinalIgnoreCase)){int end=FindLoopEnd(lines,i+1);var cond=t[4..^10].Trim();AddArrow(cx,y-34,cx,y);AddFlowNode(i+1,cond,cx,y,w,h,"decision");double bodyX=cx+145,bodyY=y+82;AddWhileTrueBranch(cx+w/2,y+h/2,bodyX,bodyY);var bodyEnd=DrawFlowRange(lines,i+1,end,bodyX,bodyY);double bodyBottom=bodyEnd-22;AddWhileLoopBack(bodyX,bodyBottom,cx,y-8);double exitY=Math.Max(bodyEnd+20,y+130);AddWhileFalseExit(cx-w/2,y+h/2,cx,exitY);y=exitY;i=end;continue;}if(t.StartsWith("ΓΙΑ ",StringComparison.OrdinalIgnoreCase)){var fm=System.Text.RegularExpressions.Regex.Match(t,@"^ΓΙΑ\s+([\p{L}_][\p{L}\p{N}_]*)\s+ΑΠΟ\s+(.+?)\s+ΜΕΧΡΙ\s+(.+?)(?:\s+ΜΕ_ΒΗΜΑ\s+(.+))?$",System.Text.RegularExpressions.RegexOptions.IgnoreCase);if(fm.Success){int end=FindLoopEnd(lines,i+1);string v=fm.Groups[1].Value,from=fm.Groups[2].Value,to=fm.Groups[3].Value,step=fm.Groups[4].Success?fm.Groups[4].Value:"1";AddArrow(cx,y-34,cx,y);AddFlowNode(i+1,$"{v} ← {from}",cx,y,w,h,"process");y+=78;AddArrow(cx,y-26,cx,y);string cmp=step.TrimStart().StartsWith("-")?$"{v} ≥ {to}":$"{v} ≤ {to}";AddFlowNode(i+1,cmp,cx,y,w,h,"decision");double bodyX=cx+145,bodyY=y+82;AddWhileTrueBranch(cx+w/2,y+h/2,bodyX,bodyY);var bodyEnd=DrawFlowRange(lines,i+1,end,bodyX,bodyY);AddArrow(bodyX,bodyEnd-26,bodyX,bodyEnd);AddFlowNode(i+1,$"{v} ← {v} + ({step})",bodyX,bodyEnd,w-16,h,"process");double incBottom=bodyEnd+h;AddWhileLoopBack(bodyX,incBottom,cx,y-8);double exitY=Math.Max(incBottom+35,y+155);AddWhileFalseExit(cx-w/2,y+h/2,cx,exitY);y=exitY;i=end;continue;}}if(t.StartsWith("ΑΝ ",StringComparison.OrdinalIgnoreCase)){int end=FindFlowEnd(lines,i+1,"ΤΕΛΟΣ_ΑΝ"),els=FindFlowElse(lines,i+1,end);var elseIf=FindFlowElseIf(lines,i+1,end);if(elseIf>=0)els=elseIf;var cond=t[3..];if(cond.EndsWith(" ΤΟΤΕ",StringComparison.OrdinalIgnoreCase))cond=cond[..^5].Trim();AddArrow(cx,y-34,cx,y-6);AddFlowNode(i+1,cond,cx,y,w,h,"decision");double by=y+94,lx=cx-165,rx=cx+165;AddOrthBranch(cx-w/2,y+h/2,lx,by,"ΟΧΙ",false);AddOrthBranch(cx+w/2,y+h/2,rx,by,"ΝΑΙ",true);var yesEnd=els>=0?els:end;var ry=DrawFlowRange(lines,i+1,yesEnd,rx,by);double ly;if(els>=0&&lines[els].Trim().StartsWith("ΑΛΛΙΩΣ_ΑΝ ",StringComparison.OrdinalIgnoreCase)){var eit=lines[els].Trim();var ec=eit[10..];if(ec.EndsWith(" ΤΟΤΕ",StringComparison.OrdinalIgnoreCase))ec=ec[..^5].Trim();AddFlowNode(els+1,ec,lx,by,w,h,"decision");int plainElse=FindFlowElse(lines,els+1,end);double eBy=by+94,eLx=lx-130,eRx=lx+130;AddOrthBranch(lx-w/2,by+h/2,eLx,eBy,"ΟΧΙ",false);AddOrthBranch(lx+w/2,by+h/2,eRx,eBy,"ΝΑΙ",true);var noY=DrawFlowRange(lines,plainElse>=0?plainElse+1:end,end,eLx,eBy);var yesY=DrawFlowRange(lines,els+1,plainElse>=0?plainElse:end,eRx,eBy);ly=Math.Max(noY,yesY)+30;AddMergeArrow(eLx,noY-25,lx,ly);AddMergeArrow(eRx,yesY-25,lx,ly);}else ly=DrawFlowRange(lines,els>=0?els+1:end,end,lx,by);y=Math.Max(ly,ry)+38;AddMergeArrow(lx,ly-25,cx,y);AddMergeArrow(rx,ry-25,cx,y);i=end;continue;}if(t=="ΑΛΛΙΩΣ"||t=="ΤΕΛΟΣ_ΑΝ")continue;var display=FlowDisplay(t);var kind=FlowKind(t);AddArrow(cx,y-34,cx,y);AddFlowNode(i+1,display,cx,y,w,h,kind);y+=78;}
  AddArrow(cx,y-34,cx,y-6);AddFlowNode(-1,"ΤΕΛΟΣ",cx,y,w,h,"start");FlowCanvas.Height=Math.Max(900,y+120);FlowCanvas.Width=760;
 }
 bool SkipFlow(string t)=>string.IsNullOrWhiteSpace(t)||t.StartsWith("!")||t.StartsWith("ΠΡΟΓΡΑΜΜΑ",StringComparison.OrdinalIgnoreCase)||t=="ΜΕΤΑΒΛΗΤΕΣ"||t.StartsWith("ΑΚΕΡΑΙΕΣ:")||t.StartsWith("ΠΡΑΓΜΑΤΙΚΕΣ:")||t.StartsWith("ΧΑΡΑΚΤΗΡΕΣ:")||t.StartsWith("ΛΟΓΙΚΕΣ:")||t=="ΑΡΧΗ"||t.StartsWith("ΤΕΛΟΣ_ΠΡΟΓΡΑΜΜΑΤΟΣ")||t=="ΤΕΛΟΣ"||t=="ΤΕΛΟΣ_ΕΠΑΝΑΛΗΨΗΣ";
 int FindLoopEnd(string[] a,int from){int depth=0;for(int i=from;i<a.Length;i++){var t=a[i].Trim();if((t.StartsWith("ΟΣΟ ",StringComparison.OrdinalIgnoreCase)&&t.EndsWith(" ΕΠΑΝΑΛΑΒΕ",StringComparison.OrdinalIgnoreCase))||t.StartsWith("ΓΙΑ ",StringComparison.OrdinalIgnoreCase))depth++;else if(t=="ΤΕΛΟΣ_ΕΠΑΝΑΛΗΨΗΣ"){if(depth==0)return i;depth--;}}return a.Length-1;}
 void AddWhileTrueBranch(double diamondRight,double diamondY,double bodyX,double bodyTop){var s=B(_dark?"#94A3B8":"#475569");AddSegment(diamondRight,diamondY,bodyX,diamondY,s);AddArrow(bodyX,diamondY,bodyX,bodyTop);AddBranchLabel("ΝΑΙ",diamondRight+10,diamondY-24);}
 void AddWhileFalseExit(double diamondLeft,double diamondY,double targetX,double targetY){var s=B(_dark?"#94A3B8":"#475569");double lane=diamondLeft-45;AddSegment(diamondLeft,diamondY,lane,diamondY,s);AddSegment(lane,diamondY,lane,targetY-20,s);AddSegment(lane,targetY-20,targetX,targetY-20,s);AddArrow(targetX,targetY-20,targetX,targetY);AddBranchLabel("ΟΧΙ",diamondLeft-38,diamondY-24);}
 void AddWhileLoopBack(double bodyX,double bodyBottom,double entryX,double entryY){var s=B(_dark?"#94A3B8":"#475569");double lane=bodyX+115,top=entryY-18;AddSegment(bodyX,bodyBottom,lane,bodyBottom,s);AddSegment(lane,bodyBottom,lane,top,s);AddSegment(lane,top,entryX,top,s);AddArrow(entryX,top,entryX,entryY);}
 void AddBranchLabel(string text,double x,double y){var l=new TextBlock{Text=text,Foreground=B(_dark?"#FBBF24":"#92400E"),FontWeight=FontWeights.Bold,FontSize=12,Background=B(_dark?"#0F192B":"#F8FAFC"),Padding=new Thickness(3,1,3,1)};Canvas.SetLeft(l,x);Canvas.SetTop(l,y);FlowCanvas.Children.Add(l);}
 void AddLoopBack(double x1,double y1,double decisionX,double decisionY){var stroke=B(_dark?"#94A3B8":"#475569");double outer=x1+145;AddSegment(x1,y1,outer,y1,stroke);AddSegment(outer,y1,outer,decisionY,stroke);AddArrow(outer,decisionY,decisionX+6,decisionY);}
 void AddLoopExit(double x1,double y1,double targetX,double targetY,string caption){var stroke=B(_dark?"#94A3B8":"#475569");double outer=x1-45;AddSegment(x1,y1,outer,y1,stroke);AddSegment(outer,y1,outer,targetY-20,stroke);AddSegment(outer,targetY-20,targetX,targetY-20,stroke);AddArrow(targetX,targetY-20,targetX,targetY-6);var l=new TextBlock{Text=caption,Foreground=B(_dark?"#FBBF24":"#92400E"),FontWeight=FontWeights.Bold,FontSize=12,Background=B(_dark?"#0F192B":"#F8FAFC"),Padding=new Thickness(3,1,3,1)};Canvas.SetLeft(l,x1-38);Canvas.SetTop(l,y1-23);FlowCanvas.Children.Add(l);}
 int FindFlowEnd(string[] a,int from,string token){for(int i=from,depth=0;i<a.Length;i++){var t=a[i].Trim();if(t.StartsWith("ΑΝ "))depth++;if(t==token){if(depth==0)return i;depth--;}}return a.Length-1;}
 int FindFlowElseIf(string[] a,int from,int end){for(int i=from,depth=0;i<end;i++){var t=a[i].Trim();if(t.StartsWith("ΑΝ "))depth++;else if(t=="ΤΕΛΟΣ_ΑΝ")depth--;else if(t.StartsWith("ΑΛΛΙΩΣ_ΑΝ ",StringComparison.OrdinalIgnoreCase)&&depth==0)return i;}return -1;}
 int FindFlowElse(string[] a,int from,int end){for(int i=from,depth=0;i<end;i++){var t=a[i].Trim();if(t.StartsWith("ΑΝ "))depth++;else if(t=="ΤΕΛΟΣ_ΑΝ")depth--;else if(t=="ΑΛΛΙΩΣ"&&depth==0)return i;}return -1;}
 double DrawFlowRange(string[] lines,int from,int to,double x,double y){const double w=180,h=42;var start=y;for(int i=from;i<to;i++){var t=lines[i].Trim();if(SkipFlow(t)||t=="ΑΛΛΙΩΣ"||t=="ΤΕΛΟΣ_ΑΝ"||t.StartsWith("ΑΛΛΙΩΣ_ΑΝ ",StringComparison.OrdinalIgnoreCase))continue;if(y>start)AddArrow(x,y-32,x,y);AddFlowNode(i+1,FlowDisplay(t),x,y,w,h,FlowKind(t));y+=60;}if(y==start){AddFlowNode(0,"—",x,y,w,h,"process");y+=70;}return y;}
 string FlowDisplay(string t){if(t.StartsWith("ΑΝ ")&&t.EndsWith(" ΤΟΤΕ",StringComparison.OrdinalIgnoreCase))return t[3..^5].Trim();if(t.StartsWith("ΑΛΛΙΩΣ_ΑΝ ")&&t.EndsWith(" ΤΟΤΕ",StringComparison.OrdinalIgnoreCase))return t[10..^5].Trim();if(t.StartsWith("ΟΣΟ ")&&t.EndsWith(" ΕΠΑΝΑΛΑΒΕ",StringComparison.OrdinalIgnoreCase))return t[4..^10].Trim();if(t.StartsWith("ΜΕΧΡΙΣ_ΟΤΟΥ "))return t[12..].Trim();return t;}
 string FlowKind(string t)=>t.StartsWith("ΑΝ ")||t.StartsWith("ΟΣΟ ")||t.StartsWith("ΓΙΑ ")||t.StartsWith("ΜΕΧΡΙΣ_ΟΤΟΥ ")?"decision":t.StartsWith("ΔΙΑΒΑΣΕ ")||t.StartsWith("ΓΡΑΨΕ ")||t.StartsWith("ΕΜΦΑΝΙΣΕ ")?"io":"process";
 void AddOrthBranch(double x1,double y1,double x2,double y2,string caption,bool right){var stroke=B(_dark?"#94A3B8":"#475569");double elbowY=y2-28;AddSegment(x1,y1,x2,y1,stroke);AddSegment(x2,y1,x2,elbowY,stroke);AddArrow(x2,elbowY,x2,y2-6);var l=new TextBlock{Text=caption,Foreground=B(_dark?"#FBBF24":"#92400E"),FontWeight=FontWeights.Bold,FontSize=12,Background=B(_dark?"#0F192B":"#F8FAFC"),Padding=new Thickness(3,1,3,1)};Canvas.SetLeft(l,right?x1+8:x1-38);Canvas.SetTop(l,y1-23);FlowCanvas.Children.Add(l);}
 void AddMergeArrow(double x1,double y1,double x2,double y2){var stroke=B(_dark?"#94A3B8":"#475569");double mid=y2-22;AddSegment(x1,y1,x1,mid,stroke);AddSegment(x1,mid,x2,mid,stroke);AddArrow(x2,mid,x2,y2-6);}
 void AddSegment(double x1,double y1,double x2,double y2,Brush stroke){FlowCanvas.Children.Add(new Line{X1=x1,Y1=y1,X2=x2,Y2=y2,Stroke=stroke,StrokeThickness=2});}
 void AddArrow(double x1,double y1,double x2,double y2){var stroke=B(_dark?"#64748B":"#64748B");var line=new Line{X1=x1,Y1=y1,X2=x2,Y2=y2,Stroke=stroke,StrokeThickness=2};FlowCanvas.Children.Add(line);double dx=x2-x1,dy=y2-y1,len=Math.Sqrt(dx*dx+dy*dy);if(len<1)return;double ux=dx/len,uy=dy/len,px=-uy,py=ux,back=10,half=5;var head=new Polygon{Points=new PointCollection{new(x2,y2),new(x2-ux*back+px*half,y2-uy*back+py*half),new(x2-ux*back-px*half,y2-uy*back-py*half)},Fill=stroke};FlowCanvas.Children.Add(head);}
 void AddFlowNode(int line,string text,double cx,double y,double w,double h,string kind){Shape shape;if(kind=="decision")shape=new Polygon{Points=new PointCollection{new(cx,y-8),new(cx+w/2,y+h/2),new(cx,y+h+8),new(cx-w/2,y+h/2)}};else if(kind=="io"){var skew=22;shape=new Polygon{Points=new PointCollection{new(cx-w/2+skew,y),new(cx+w/2,y),new(cx+w/2-skew,y+h),new(cx-w/2,y+h)}};}else{shape=new Rectangle{RadiusX=kind=="start"?22:8,RadiusY=kind=="start"?22:8,Width=w,Height=h};Canvas.SetLeft(shape,cx-w/2);Canvas.SetTop(shape,y);}shape.Fill=B(_dark?"#18243A":"#FFFFFF");shape.Stroke=B(kind=="decision"?"#F59E0B":kind=="io"?"#06B6D4":"#6366F1");shape.StrokeThickness=2.2;FlowCanvas.Children.Add(shape);var label=new TextBlock{Text=text,Foreground=B(_dark?"#E8EEF8":"#172033"),FontFamily=new FontFamily("Cascadia Mono,Consolas"),FontSize=14,FontWeight=FontWeights.SemiBold,TextWrapping=TextWrapping.Wrap,TextAlignment=TextAlignment.Center,Width=w-34,Height=h,IsHitTestVisible=false};label.Padding=new Thickness(4,Math.Max(4,(h-28)/2),4,0);Canvas.SetLeft(label,cx-w/2+17);Canvas.SetTop(label,y);FlowCanvas.Children.Add(label);if(line>0)_flowShapes[line]=shape;}
 void HighlightFlowLine(int line){foreach(var s in _flowShapes.Values)s.StrokeThickness=2;if(_flowShapes.TryGetValue(line,out var active)){active.Stroke=B("#22C55E");active.StrokeThickness=5;}}
 void PrepareTrace(){var r=_interpreter.Run(CodeText(),PromptInput);_stepIndex=-1;ConsoleBox.Text="Βηματική εκτέλεση έτοιμη — πάτησε ξανά Βήμα (F10).";TraceGrid.ItemsSource=null;VariablesGrid.ItemsSource=null;StatusText.Text=$"Έτοιμα {_interpreter.Trace.Count} βήματα";}
 void Step_Click(object s,RoutedEventArgs e){try{if(_stepIndex<0){PrepareTrace();_stepIndex=0;}else _stepIndex++;if(_interpreter.Trace.Count==0){StatusText.Text="Δεν υπάρχουν εκτελέσιμες εντολές";return;}if(_stepIndex>=_interpreter.Trace.Count){StatusText.Text="Τέλος βηματικής εκτέλεσης";StatusDot.Fill=B("#22C55E");_stepIndex=-1;return;}var step=_interpreter.Trace[_stepIndex];Editor.ScrollToLine(step.Line);var dl=Editor.Document.GetLineByNumber(step.Line);Editor.Select(dl.Offset,dl.Length);VariablesGrid.ItemsSource=step.Variables.Select(v=>new{Name=v.Key,Value=v.Value}).ToList();ConsoleBox.Text=string.IsNullOrWhiteSpace(step.Output)?$"Γραμμή {step.Line}: {step.Statement}":step.Output;TraceGrid.ItemsSource=_interpreter.Trace.Take(_stepIndex+1).Select((t,n)=>new{Βήμα=n+1,Γραμμή=t.Line,Εντολή=t.Statement,Τιμές=string.Join(", ",t.Variables.Where(v=>v.Value!=null).Select(v=>$"{v.Key}={v.Value}"))}).ToList();HighlightFlowLine(step.Line);StatusText.Text=$"Βήμα {_stepIndex+1}/{_interpreter.Trace.Count} — γραμμή {step.Line}";StatusDot.Fill=B("#F59E0B");}catch(Exception ex){ConsoleBox.Text="Σφάλμα: "+ex.Message;StatusText.Text="Σφάλμα βηματικής εκτέλεσης";StatusDot.Fill=B("#EF4444");_stepIndex=-1;}}
 void FormatCode(){
  var lines=CodeText().Replace("\r","").Split('\n');var result=new List<string>();int indent=0;bool vars=false;
  foreach(var raw in lines){var t=raw.Trim();if(t.Length==0){result.Add("");continue;}var u=t.ToUpperInvariant();
   if(u=="ΑΡΧΗ"){vars=false;indent=0;result.Add(t);indent=1;continue;}
   if(u=="ΜΕΤΑΒΛΗΤΕΣ"){vars=true;indent=0;result.Add(t);continue;}
   if(u.StartsWith("ΤΕΛΟΣ_ΠΡΟΓΡΑΜΜΑΤΟΣ")||u=="ΤΕΛΟΣ"){indent=0;result.Add(t);continue;}
   bool close=u=="ΑΛΛΙΩΣ"||u.StartsWith("ΑΛΛΙΩΣ_ΑΝ ")||u=="ΤΕΛΟΣ_ΑΝ"||u=="ΤΕΛΟΣ_ΕΠΑΝΑΛΗΨΗΣ"||u.StartsWith("ΜΕΧΡΙΣ_ΟΤΟΥ ");
   if(close)indent=Math.Max(1,indent-1);
   var level=vars&&u!="ΜΕΤΑΒΛΗΤΕΣ"?1:indent;result.Add(new string(' ',Math.Max(0,level)*2)+t);
   bool open=(u.StartsWith("ΑΝ ")&&u.EndsWith(" ΤΟΤΕ"))||(u.StartsWith("ΟΣΟ ")&&u.EndsWith(" ΕΠΑΝΑΛΑΒΕ"))||u.StartsWith("ΓΙΑ ")||u=="ΑΡΧΗ_ΕΠΑΝΑΛΗΨΗΣ"||u=="ΑΛΛΙΩΣ"||u.StartsWith("ΑΛΛΙΩΣ_ΑΝ ");
   if(open)indent++;
  }
  var caret=Editor.CaretOffset;SetCode(string.Join(Environment.NewLine,result));Editor.CaretOffset=Math.Min(caret,Editor.Text.Length);
 }
 void Run_Click(object s,RoutedEventArgs e){try{FormatCode();var r=_interpreter.Run(CodeText(),PromptInput);ConsoleBox.Text=string.IsNullOrWhiteSpace(r)?"✓ Η εκτέλεση ολοκληρώθηκε.":r;VariablesGrid.ItemsSource=_interpreter.Variables.Select(v=>new{Name=v.Key,Value=v.Value}).ToList();StatusText.Text="Η εκτέλεση ολοκληρώθηκε";StatusDot.Fill=B("#22C55E");}catch(Exception ex){ConsoleBox.Text="Σφάλμα: "+ex.Message;StatusText.Text="Σφάλμα εκτέλεσης";StatusDot.Fill=B("#EF4444");}}
 string PromptInput(string name){var w=new Window{Title="ΔΙΑΒΑΣΕ — "+name,Width=380,Height=160,WindowStartupLocation=WindowStartupLocation.CenterOwner,Owner=this,ResizeMode=ResizeMode.NoResize};var g=new Grid{Margin=new Thickness(18)};g.RowDefinitions.Add(new RowDefinition());g.RowDefinitions.Add(new RowDefinition());g.RowDefinitions.Add(new RowDefinition());var label=new TextBlock{Text=$"Δώσε τιμή για τη μεταβλητή {name}:",Margin=new Thickness(0,0,0,8)};var box=new TextBox{Height=28};var ok=new Button{Content="OK",Width=80,Height=28,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,8,0,0),IsDefault=true};Grid.SetRow(box,1);Grid.SetRow(ok,2);g.Children.Add(label);g.Children.Add(box);g.Children.Add(ok);w.Content=g;ok.Click+=(_,__)=>w.DialogResult=true;w.Loaded+=(_,__)=>box.Focus();if(w.ShowDialog()!=true)throw new InvalidOperationException("Η εισαγωγή ακυρώθηκε.");return box.Text;}
 void Clear_Click(object s,RoutedEventArgs e){_stepIndex=-1;ConsoleBox.Clear();VariablesGrid.ItemsSource=null;TraceGrid.ItemsSource=null;StatusText.Text="Έτοιμο";StatusDot.Fill=B("#22C55E");}
 void New_Click(object s,RoutedEventArgs e){SetCode("");_file=null;FileText.Text="χωρίς τίτλο.glossa";StatusText.Text="Νέο αρχείο";}
 void Open_Click(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="Αρχεία Algora (*.glossa;*.algo)|*.glossa;*.algo|Αρχεία κειμένου (*.txt)|*.txt|Όλα τα αρχεία|*.*"};if(d.ShowDialog()==true){SetCode(File.ReadAllText(d.FileName));_file=d.FileName;FileText.Text=System.IO.Path.GetFileName(_file);StatusText.Text="Το αρχείο άνοιξε";}}
 void Save_Click(object s,RoutedEventArgs e){if(_file==null){var d=new SaveFileDialog{Filter="Αρχείο ΓΛΩΣΣΑΣ (*.glossa)|*.glossa|Αλγόριθμος (*.algo)|*.algo|Αρχείο κειμένου (*.txt)|*.txt",DefaultExt=".glossa"};if(d.ShowDialog()!=true)return;_file=d.FileName;}File.WriteAllText(_file,CodeText());FileText.Text=System.IO.Path.GetFileName(_file);StatusText.Text="Αποθηκεύτηκε";}
 void Editor_TextChanged(object? s,EventArgs e){StatusText.Text="Επεξεργασία";if(IsLoaded&&WorkTabs.SelectedIndex==1)BuildFlowchart();}
 void Editor_KeyDown(object s,KeyEventArgs e){if(e.Key==Key.Back){var line=Editor.Document.GetLineByOffset(Editor.CaretOffset);var before=Editor.Document.GetText(line.Offset,Math.Max(0,Editor.CaretOffset-line.Offset));if(before.Length>0&&before.All(char.IsWhiteSpace)){int remove=before.EndsWith("  ")?2:1;Editor.Document.Remove(Editor.CaretOffset-remove,remove);Editor.CaretOffset-=remove;e.Handled=true;return;}}if(e.Key==Key.Space||e.Key==Key.Enter||e.Key==Key.Tab){NormalizeWordBeforeCaret();}if(e.Key==Key.F5){Run_Click(s,new RoutedEventArgs());e.Handled=true;return;}if(e.Key==Key.F10){Step_Click(s,new RoutedEventArgs());e.Handled=true;return;}if(e.Key==Key.Enter){var line=Editor.Document.GetLineByOffset(Editor.CaretOffset);var text=Editor.Document.GetText(line.Offset,Math.Max(0,Editor.CaretOffset-line.Offset));var indent=new string(text.TakeWhile(char.IsWhiteSpace).ToArray());var trimmed=text.TrimStart();if(trimmed.StartsWith("ΑΝ ",StringComparison.OrdinalIgnoreCase)||trimmed.StartsWith("ΓΙΑ ",StringComparison.OrdinalIgnoreCase)||trimmed.StartsWith("ΟΣΟ ",StringComparison.OrdinalIgnoreCase)||trimmed.Equals("ΑΡΧΗ_ΕΠΑΝΑΛΗΨΗΣ",StringComparison.OrdinalIgnoreCase))indent+="  ";Editor.Document.Insert(Editor.CaretOffset,Environment.NewLine+indent);Editor.CaretOffset+=Environment.NewLine.Length+indent.Length;e.Handled=true;}}
 void NormalizeWordBeforeCaret(){int p=Editor.CaretOffset;if(p<=0)return;var text=Editor.Document.Text;int end=p;while(end>0&&char.IsWhiteSpace(text[end-1]))end--;int start=end;while(start>0&&(char.IsLetter(text[start-1])||text[start-1]=='_'))start--;if(end<=start)return;var word=text[start..end];var kw=Keywords.FirstOrDefault(k=>string.Equals(k,word,StringComparison.CurrentCultureIgnoreCase));if(kw!=null&&word!=kw){Editor.Document.Replace(start,end-start,kw);Editor.CaretOffset=p+(kw.Length-word.Length);}}
 void Editor_TextEntered(object s,TextCompositionEventArgs e){if(string.IsNullOrWhiteSpace(e.Text))return;var p=Editor.CaretOffset;var text=Editor.Document.Text;int start=p;while(start>0&&(char.IsLetter(text[start-1])||text[start-1]=='_'))start--;var prefix=text[start..p];if(prefix.Length<2)return;var matches=Keywords.Where(k=>k.StartsWith(prefix,StringComparison.CurrentCultureIgnoreCase)).Take(12).ToList();if(matches.Count==0)return;_completion?.Close();_completion=new CompletionWindow(Editor.TextArea);foreach(var k in matches)_completion.CompletionList.CompletionData.Add(new KeywordCompletion(k,prefix.Length));_completion.StartOffset=start;_completion.EndOffset=p;_completion.Show();_completion.Closed+=(_,__)=>_completion=null;}
 sealed class KeywordCompletion:ICSharpCode.AvalonEdit.CodeCompletion.ICompletionData{readonly int _prefixLength;public KeywordCompletion(string text,int prefixLength){Text=text;_prefixLength=prefixLength;}public System.Windows.Media.ImageSource? Image=>null;public string Text{get;}public object Content=>Text;public object Description=>"Δεσμευμένη λέξη ΓΛΩΣΣΑΣ";public double Priority=>0;public void Complete(ICSharpCode.AvalonEdit.Editing.TextArea area,ICSharpCode.AvalonEdit.Document.ISegment segment,EventArgs e){var end=area.Caret.Offset;var start=Math.Max(0,end-_prefixLength);area.Document.Replace(start,end-start,Text);area.Caret.Offset=start+Text.Length;}}
 void Window_KeyDown(object s,KeyEventArgs e){if(e.Key==Key.Escape&&_focusMode){Focus_Click(s,new RoutedEventArgs());return;}if(e.Key==Key.F9){Focus_Click(s,new RoutedEventArgs());return;}if(e.Key!=Key.F11)return;if(WindowStyle!=WindowStyle.None){_oldStyle=WindowStyle;_oldState=WindowState;WindowStyle=WindowStyle.None;WindowState=WindowState.Maximized;}else{WindowStyle=_oldStyle;WindowState=_oldState;}}
